"""
tests/fixtures/ground_truth_script.py — Step 1.3 ground truth baseline.

PURPOSE
-------
This is the manually-written, hand-crafted Playwright automation for the
BrowserBot MVP demo workflow.  It is NOT generated by BrowserBot.  It is
the ground truth that the BrowserBot generation pipeline must reproduce
automatically in later phases.

WORKFLOW (from docs/1. ProductRequirement.md — Locked Demo Scenario)
---------------------------------------------------------------------
1. Open the Mock Order Tracking Portal
2. Log in using demo credentials
3. Enter an Order ID
4. Submit the lookup form
5. Read the displayed shipment status
6. Print the result to stdout

DEMO SITE
---------
Target: Mock Order Tracking Portal (authenticated demo website)

The execution plan specifies a "Mock Order Tracking Portal" without locking
to a specific URL at Phase 0.  This script uses configuration constants
(DEMO_URL, DEMO_USERNAME, etc.) that must be set to the actual demo site
before running.

If BROWSERBOT_DEMO_URL, BROWSERBOT_DEMO_USERNAME, BROWSERBOT_DEMO_PASSWORD,
and BROWSERBOT_DEMO_ORDER_ID are set as environment variables (or in .env),
they take precedence over the constants below.

RELIABILITY BASELINE
--------------------
Run 10 consecutive times to establish the Phase 9 baseline success rate:

    Windows PowerShell:
        for ($i=1; $i -le 10; $i++) {
            python tests/fixtures/ground_truth_script.py
        }

    Linux / macOS:
        for i in {1..10}; do python tests/fixtures/ground_truth_script.py; done

Record pass/fail in the table inside context/run_01.md.

VERIFICATION
------------
Run:
    python tests/fixtures/ground_truth_script.py

Expected output (on success):
    ✅  Order status retrieved successfully
    Order ID : <order_id>
    Status   : <status text from the page>
    Carrier  : <carrier name if present>
    Delivery : <expected delivery if present>
"""

from __future__ import annotations

import asyncio
import os
import sys
import textwrap
import time
from dataclasses import dataclass
from pathlib import Path

# ---------------------------------------------------------------------------
# Load .env (optional — never required on the default Ollama path)
# ---------------------------------------------------------------------------
try:
    from dotenv import load_dotenv

    _dotenv = Path(__file__).resolve().parents[2] / ".env"
    load_dotenv(dotenv_path=_dotenv, override=False)
except ImportError:
    pass  # python-dotenv not installed in the test runner env; fine

# ---------------------------------------------------------------------------
# Demo site configuration
#
# Override any constant by setting the corresponding environment variable.
# These defaults intentionally fail loudly so the developer must consciously
# configure the target site — not accidentally run against a wrong endpoint.
# ---------------------------------------------------------------------------

DEMO_URL: str = os.getenv(
    "BROWSERBOT_DEMO_URL",
    # TODO: Replace with the actual Mock Order Tracking Portal URL.
    # See docs/1. ProductRequirement.md — Locked Demo Scenario.
    "https://YOUR_DEMO_SITE_URL_HERE",
)

DEMO_USERNAME: str = os.getenv(
    "BROWSERBOT_DEMO_USERNAME",
    # TODO: Replace with the demo account username.
    "demo_user",
)

DEMO_PASSWORD: str = os.getenv(
    "BROWSERBOT_DEMO_PASSWORD",
    # TODO: Replace with the demo account password.
    # This value is NEVER written to any log or artifact (PII scrubbing, NFR).
    "demo_password",
)

DEMO_ORDER_ID: str = os.getenv(
    "BROWSERBOT_DEMO_ORDER_ID",
    # TODO: Replace with a valid test order ID on the demo site.
    "12345",
)

# Playwright timing configuration
PAGE_LOAD_TIMEOUT_MS: int = int(os.getenv("BROWSERBOT_PAGE_TIMEOUT_MS", "30000"))
ACTION_TIMEOUT_MS: int = int(os.getenv("BROWSERBOT_ACTION_TIMEOUT_MS", "10000"))
HEADLESS: bool = os.getenv("BROWSERBOT_HEADLESS", "true").lower() in (
    "1",
    "true",
    "yes",
)


# ---------------------------------------------------------------------------
# Result dataclass
# ---------------------------------------------------------------------------


@dataclass
class OrderStatus:
    """Structured result returned by the automation."""

    order_id: str
    status: str
    carrier: str | None = None
    expected_delivery: str | None = None
    raw_page_text: str | None = None


# ---------------------------------------------------------------------------
# Ground truth automation
# ---------------------------------------------------------------------------


async def check_order_status(order_id: str) -> OrderStatus:
    """
    Perform the complete order-status lookup workflow on the demo site.

    This is the *ground truth* implementation.  Every selector, wait strategy,
    and extraction pattern here defines what the BrowserBot generation pipeline
    must reproduce automatically when given a recording of this session.

    Args:
        order_id: The order identifier to look up.

    Returns:
        :class:`OrderStatus` with the extracted shipment information.

    Raises:
        RuntimeError: If any automation step fails.
    """
    from playwright.async_api import Page, async_playwright

    # Guard: fail immediately if URL is still the placeholder.
    if "YOUR_DEMO_SITE_URL_HERE" in DEMO_URL:
        raise RuntimeError(
            "DEMO_URL is not configured.\n"
            "Set BROWSERBOT_DEMO_URL in your .env file or environment.\n"
            "See tests/fixtures/ground_truth_script.py for details."
        )

    async with async_playwright() as pw:
        browser = await pw.chromium.launch(
            headless=HEADLESS,
            slow_mo=0,  # no slow-mo on the ground truth — speed matters for reliability
        )
        context = await browser.new_context(
            viewport={"width": 1280, "height": 800},
        )
        page: Page = await context.new_page()

        # Set default timeouts for all operations.
        page.set_default_timeout(ACTION_TIMEOUT_MS)
        page.set_default_navigation_timeout(PAGE_LOAD_TIMEOUT_MS)

        try:
            # ----------------------------------------------------------------
            # Step 1: Navigate to the demo site
            # ----------------------------------------------------------------
            await page.goto(DEMO_URL, wait_until="networkidle")

            # ----------------------------------------------------------------
            # Step 2: Log in with demo credentials
            #
            # Selectors below use Playwright's semantic locators (get_by_role,
            # get_by_label, get_by_placeholder) rather than brittle CSS/XPath.
            # This matches the robustness strategy defined in the architecture
            # (Risk R-04 mitigation, Phase 8.1 selector strategy).
            #
            # TODO: Update these selectors to match the actual demo site's
            # login form structure.  The locators here follow common patterns
            # (labelled username/password fields + submit button).
            # ----------------------------------------------------------------
            await page.get_by_label("Username").fill(DEMO_USERNAME)
            await page.get_by_label("Password").fill(DEMO_PASSWORD)
            await page.get_by_role("button", name="Login").click()

            # Wait for the authenticated dashboard to load.
            await page.wait_for_load_state("networkidle")

            # ----------------------------------------------------------------
            # Step 3: Navigate to the order lookup / search form
            #
            # TODO: Update if the demo site requires navigating to a specific
            # page before the order-ID field is visible.
            # ----------------------------------------------------------------
            # Example: await page.get_by_role("link", name="Order Lookup").click()
            # await page.wait_for_load_state("networkidle")

            # ----------------------------------------------------------------
            # Step 4: Enter the order ID and submit
            #
            # TODO: Update the label/placeholder to match the actual form field.
            # ----------------------------------------------------------------
            await page.get_by_label("Order ID").fill(order_id)
            await page.get_by_role("button", name="Track").click()
            await page.wait_for_load_state("networkidle")

            # ----------------------------------------------------------------
            # Step 5: Extract the order status from the results page
            #
            # TODO: Replace these selectors with the actual page structure.
            # Use semantic locators wherever possible (role, text, label).
            # ----------------------------------------------------------------
            status_text: str = await page.get_by_test_id("order-status").inner_text()

            # Optional fields — only extracted if present on the page.
            carrier: str | None = None
            expected_delivery: str | None = None

            carrier_el = page.get_by_test_id("carrier-name")
            if await carrier_el.count() > 0:
                carrier = await carrier_el.inner_text()

            delivery_el = page.get_by_test_id("expected-delivery")
            if await delivery_el.count() > 0:
                expected_delivery = await delivery_el.inner_text()

            # Capture full page text for debugging and reliability analysis.
            raw_page_text: str = await page.inner_text("body")

            return OrderStatus(
                order_id=order_id,
                status=status_text.strip(),
                carrier=carrier.strip() if carrier else None,
                expected_delivery=expected_delivery.strip()
                if expected_delivery
                else None,
                raw_page_text=raw_page_text[:2000],  # cap for log readability
            )

        except Exception as exc:
            # Capture a screenshot on failure for debugging.
            screenshot_path = Path(__file__).parent / "failure_screenshot.png"
            try:
                await page.screenshot(path=str(screenshot_path))
                print(
                    f"  Screenshot saved: {screenshot_path}",
                    file=sys.stderr,
                )
            except Exception:  # noqa: BLE001
                pass
            raise RuntimeError(
                f"Ground truth script failed at runtime: {exc}"
            ) from exc

        finally:
            await context.close()
            await browser.close()


# ---------------------------------------------------------------------------
# Entry point — `python tests/fixtures/ground_truth_script.py`
# ---------------------------------------------------------------------------


def main() -> None:
    """
    Run the order-status workflow and print the result to stdout.

    Prints the scraped status text to stdout (as required by Step 1.3).
    Exits 0 on success, 1 on failure.
    """
    start = time.perf_counter()

    print(f"\nBrowserBot — Ground Truth Script (Step 1.3)")
    print(f"Demo URL  : {DEMO_URL}")
    print(f"Order ID  : {DEMO_ORDER_ID}")
    print(f"Headless  : {HEADLESS}")
    print("-" * 50)

    try:
        result: OrderStatus = asyncio.run(check_order_status(DEMO_ORDER_ID))
        elapsed = time.perf_counter() - start

        print("\n✅  Order status retrieved successfully")
        print(f"Order ID  : {result.order_id}")
        print(f"Status    : {result.status}")
        if result.carrier:
            print(f"Carrier   : {result.carrier}")
        if result.expected_delivery:
            print(f"Delivery  : {result.expected_delivery}")
        print(f"\nElapsed   : {elapsed:.2f}s")

    except RuntimeError as exc:
        elapsed = time.perf_counter() - start
        print(f"\n❌  Ground truth script FAILED ({elapsed:.2f}s)")
        print(textwrap.indent(str(exc), "    "), file=sys.stderr)
        sys.exit(1)


if __name__ == "__main__":
    main()
